package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class BigMatrixImpl_operate_TriageGen2Test {

    private static final BigDecimal ZERO = BigDecimal.ZERO;
    private static final BigDecimal ONE = BigDecimal.ONE;
    private static final BigDecimal TWO = new BigDecimal("2");
    private static final BigDecimal THREE = new BigDecimal("3");

    @Test
    public void testOperate_Success() {
        // Matrix 2x2:
        // [ 1, 2 ]
        // [ 3, 4 ]
        BigDecimal[][] data = {
            {ONE, TWO},
            {THREE, TWO.add(TWO)}
        };
        BigMatrixImpl matrix = new BigMatrixImpl(data);

        // Vector [ 1, 0 ]
        // Expected: [ 1*1 + 2*0, 3*1 + 4*0 ] = [ 1, 3 ]
        BigDecimal[] v = {ONE, ZERO};
        BigDecimal[] expected = {ONE, THREE};

        BigDecimal[] result = matrix.operate(v);

        Assert.assertArrayEquals(expected, result);
    }











    private BigDecimal FIVE() {
        return new BigDecimal("5");
    }

    private BigDecimal TEN() {
        return new BigDecimal("10");
    }
}

